package com.example.demo.controller; import com.example.demo.model.User; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/users") public class UserController { private final List<User> users=new ArrayList<>(); public UserController(){users.add(new User(1L,"Alice Smith","alice@example.com"));users.add(new User(2L,"Bob Jones","bob@example.com"));} @PostMapping public String create(@RequestBody User u){users.add(u);return "User created successfully with ID: "+u.getId();} @GetMapping public List<User> all(){return users;} @GetMapping("/{id}") public User one(@PathVariable Long id){return users.stream().filter(u->u.getId().equals(id)).findFirst().orElse(null);} @PutMapping("/{id}") public String update(@PathVariable Long id,@RequestBody User x){for(User u:users)if(u.getId().equals(id)){u.setName(x.getName());u.setEmail(x.getEmail());return "User updated successfully!";}return "User not found!";} @DeleteMapping("/{id}") public String delete(@PathVariable Long id){return users.removeIf(u->u.getId().equals(id))?"User deleted successfully!":"User not found!";} }